package com.amd.deskhub;
import android.app.Activity;import android.os.Bundle;import android.webkit.*;import android.content.*;import org.json.*;import java.net.*;import java.io.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 android.webkit.ValueCallback<android.net.Uri[]> fileCallback;
 WebView web; ExecutorService worker=Executors.newSingleThreadExecutor(); android.content.SharedPreferences prefs;
 @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("gateway",MODE_PRIVATE);web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(true);web.getSettings().setAllowContentAccess(true);web.getSettings().setAllowFileAccessFromFileURLs(false);web.getSettings().setAllowUniversalAccessFromFileURLs(false);web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView view,ValueCallback<android.net.Uri[]> callback,FileChooserParams params){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=callback;try{startActivityForResult(params.createIntent(),101);}catch(Exception e){fileCallback=null;callback.onReceiveValue(null);}return true;}});web.addJavascriptInterface(new Host(),"Android");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}});web.loadUrl("file:///android_asset/index.html");}
 JSONObject remote(String address,String path,Object body,String token)throws Exception{if(!path.startsWith("/api/")||path.contains("..")||path.contains("?")||path.contains("#"))throw new Exception("Invalid API path");HttpURLConnection c=(HttpURLConnection)new URL(address+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(8000);c.setReadTimeout(25000);if(!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);try{if(body!=null&&body!=JSONObject.NULL){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");byte[] b=body.toString().getBytes("UTF-8");c.setFixedLengthStreamingMode(b.length);try(OutputStream o=c.getOutputStream()){o.write(b);}}int status=c.getResponseCode();if(status>=300&&status<400)throw new Exception("Gateway redirect rejected");InputStream in=status<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(in!=null)try(InputStream s=in){byte[] b=new byte[4096];int n;while((n=s.read(b))!=-1){if(bytes.size()+n>262144)throw new Exception("Response too large");bytes.write(b,0,n);}}JSONObject result=new JSONObject(bytes.toString("UTF-8"));if(status>=400)throw new Exception(result.optString("error","HTTP "+status));return result;}finally{c.disconnect();}}
 JSONObject postureStatus(String raw)throws Exception{URI u=new URI(raw);String host=u.getHost();if(!"http".equals(u.getScheme())||u.getPort()!=8768||!"/status".equals(u.getPath())||u.getUserInfo()!=null||u.getFragment()!=null||host==null||!host.matches("[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+"))throw new Exception("Invalid status address");String[] parts=host.split("\\.");int a=Integer.parseInt(parts[0]),b=Integer.parseInt(parts[1]);for(String part:parts)if(Integer.parseInt(part)>255)throw new Exception("Invalid address");if(!(a==10||a==192&&b==168||a==172&&b>=16&&b<=31))throw new Exception("LAN status only");HttpURLConnection c=(HttpURLConnection)u.toURL().openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(1500);c.setReadTimeout(1500);try{if(c.getResponseCode()!=200)throw new Exception("Status unavailable");try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){if(out.size()+n>32768)throw new Exception("Status too large");out.write(buf,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 class Host {@JavascriptInterface public void request(final String id,final String op,final String raw){worker.execute(()->{JSONObject result=new JSONObject();try{JSONObject d=new JSONObject(raw);String address=prefs.getString("address",""),token=prefs.getString("token","");if(op.equals("config")){result.put("address",address);result.put("paired",!token.isEmpty());}else if(op.equals("pair")){URI u=new URI(d.getString("address"));if(!("http".equals(u.getScheme())||"https".equals(u.getScheme()))||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||!(u.getPath().isEmpty()||u.getPath().equals("/")))throw new Exception("请输入网关根地址");address=u.getScheme()+"://"+u.getRawAuthority();JSONObject pair=remote(address,"/api/pair",new JSONObject().put("code",d.getString("code")),"");token=pair.getString("token");prefs.edit().putString("address",address).putString("token",token).apply();result.put("address",address);result.put("paired",true);}else if(op.equals("postureStatus")){result=postureStatus(d.getString("url"));}else if(op.equals("request")){if(address.isEmpty())throw new Exception("请先配置网关地址");result=remote(address,d.getString("path"),d.opt("body"),token);}else if(op.equals("export")){final String text=d.getString("text");runOnUiThread(()->{Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("text/plain");intent.putExtra(Intent.EXTRA_TEXT,text);startActivity(Intent.createChooser(intent,"导出执行记录"));});result.put("shared",true);}else throw new Exception("Unknown operation");}catch(Exception e){try{result.put("error",e.getMessage()==null?e.toString():e.getMessage());}catch(Exception ignored){}}final String js="window.nativeReply("+JSONObject.quote(id)+","+result.toString()+")";runOnUiThread(()->web.evaluateJavascript(js,null));});}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==101&&fileCallback!=null){fileCallback.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));fileCallback=null;}}
 @Override protected void onDestroy(){if(fileCallback!=null){fileCallback.onReceiveValue(null);fileCallback=null;}worker.shutdownNow();web.removeJavascriptInterface("Android");web.destroy();super.onDestroy();}
}
